// Evidence-backed request-path tests for the Bands leaf (Phase 3.1).
//
// Generated by scripts/research/gen-31-tests.py from the rows in api.md, which in turn come from
// docs/research/apk-endpoints.md. Each test calls the method and inspects the URL that actually
// reaches `fetch`, so a rename or a route regression fails here rather than in production.

import BandlabSDK from 'bandlab-sdk';

function makeClient(): BandlabSDK {
  return new BandlabSDK({ bearerToken: 'My Bearer Token', baseURL: 'http://127.0.0.1:4010' });
}

/** Run `fn`, capture the URL of the first request, and answer it with a stub response. */
async function captureURL(fn: (c: BandlabSDK) => Promise<unknown>): Promise<string> {
  const calls: string[] = [];
  const realFetch = globalThis.fetch;
  globalThis.fetch = (async (input: any) => {
    calls.push(typeof input === 'string' ? input : input?.url ?? String(input));
    return new Response('{}', { status: 200, headers: { 'content-type': 'application/json' } });
  }) as typeof fetch;
  try {
    await fn(makeClient()).catch(() => undefined);
  } finally {
    globalThis.fetch = realFetch;
  }
  if (!calls.length) throw new Error('no request was issued');
  return calls[0]!;
}

describe('Bands paths match the APK evidence', () => {
  test('GET /bands/suggested hits /bands/suggested', async () => {
    const url = await captureURL((c) => c.bands.listSuggested({}));
    expect(url).toContain('/bands/suggested');
  });

  test('GET /bands/{bandID}/followers hits /bands/{bandID}/followers', async () => {
    const url = await captureURL((c) => c.bands.listFollowers('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e', {}));
    expect(url).toContain('/bands/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/followers');
  });

  test('POST /bands/{bandID}/followers/{userID} hits /bands/{bandID}/followers/{userID}', async () => {
    const url = await captureURL((c) =>
      c.bands.addFollower('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e', '182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e'),
    );
    expect(url).toContain(
      '/bands/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/followers/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e',
    );
  });

  test('GET /bands/{bandId}/members/{userID}/follow-invitees hits /bands/{bandId}/members/{userID}/follow-invitees', async () => {
    const url = await captureURL((c) =>
      c.bands.listMemberFollowInvitees('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e', {
        bandId: '182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e',
      }),
    );
    expect(url).toContain(
      '/bands/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/members/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/follow-invitees',
    );
  });

  test('POST /bands/{bandId}/pins/posts/{postID} hits /bands/{bandId}/pins/posts/{postID}', async () => {
    const url = await captureURL((c) =>
      c.bands.pinPost('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e', {
        bandId: '182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e',
      }),
    );
    expect(url).toContain(
      '/bands/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/pins/posts/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e',
    );
  });

  test('GET /bands/{bandID}/videos/posts hits /bands/{bandID}/videos/posts', async () => {
    const url = await captureURL((c) => c.bands.listVideoPosts('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e', {}));
    expect(url).toContain('/bands/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/videos/posts');
  });

  test('GET /bands/{bandId}/invites hits /bands/{bandId}/invites and carries accepted=false', async () => {
    const url = await captureURL((c) =>
      c.bands.invites.list('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e', { accepted: false }),
    );
    expect(url).toContain('/bands/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/invites');
    expect(url).toContain('accepted=false');
  });
});
